import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL);
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

app.use(express.json());

// Rate limiting middleware
async function rateLimiter(req, res, next) {
  const key = `rl:${req.ip}:${req.path}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, 60);
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  next();
}

// Session validation
async function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const session = await redis.get(`sess:${token}`);
  if (!session) return res.status(401).json({ error: 'invalid session' });
  req.user = JSON.parse(session);
  next();
}

// Audit logging
async function auditLog(action, userId, details) {
  await pool.query(
    'INSERT INTO audit_log(action, user_id, details, ts) VALUES($1, $2, $3, NOW())',
    [action, userId, JSON.stringify(details)]
  );
}

app.use(rateLimiter);

// Public endpoint - product search with faceted filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { q, category, min_price, max_price, sort_by, order } = req.query;

    let baseQuery = `SELECT p.id, p.name, p.price, p.category, p.rating 
                     FROM products p WHERE p.active = true`;
    let params = [];
    let paramIdx = 1;

    if (q) {
      params.push(`%${q}%`);
      baseQuery += ` AND p.name ILIKE $${paramIdx++}`;
    }
    if (category) {
      params.push(category);
      baseQuery += ` AND p.category = $${paramIdx++}`;
    }
    if (min_price) {
      params.push(parseFloat(min_price));
      baseQuery += ` AND p.price >= $${paramIdx++}`;
    }
    if (max_price) {
      params.push(parseFloat(max_price));
      baseQuery += ` AND p.price <= $${paramIdx++}`;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'rating', 'name', 'created_at'];
    const sortField = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY p.${sortField} ${sortOrder} LIMIT 50`;

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'search failed' });
  }
});

// Authenticated endpoint - order history with custom reporting
app.get('/api/v2/orders/report', validateSession, async (req, res) => {
  try {
    const { start_date, end_date, group_by } = req.query;
    const userId = req.user.id;

    // Build reporting query with user-specified grouping
    let reportQuery = `SELECT ${group_by}, COUNT(*) as order_count, 
                       SUM(total_amount) as revenue
                       FROM orders WHERE user_id = $1`;
    let params = [userId];
    let paramIdx = 2;

    if (start_date) {
      params.push(start_date);
      reportQuery += ` AND created_at >= $${paramIdx++}::timestamp`;
    }
    if (end_date) {
      params.push(end_date);
      reportQuery += ` AND created_at <= $${paramIdx++}::timestamp`;
    }

    reportQuery += ` GROUP BY ${group_by}`;

    await auditLog('report_generated', userId, { group_by, start_date, end_date });
    const result = await pool.query(reportQuery, params);
    res.json({ report: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'report generation failed' });
  }
});

app.listen(3000);
